import{_ as l,a0 as d,w as p,s as o,I as i,x as e,a1 as t,A as n,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"用户、組及其它 Linux 特性 | LCTT x X-CMD","titleTemplate":false,"description":"用户、組及其它 Linux 特性 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用户、組及其它 Linux 特性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用户、組及其它 Linux 特性 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20180710 Users, Groups, and Other Linux Beasts","title":"用户、組及其它 Linux 特性","tag":"201812","desc":""},"relativePath":"201812/20180710 Users, Groups, and Other Linux Beasts.md","filePath":"[post].md"}'),u={name:"201812/20180710 Users, Groups, and Other Linux Beasts.md"};function g(h,s,c,k,b,f){const a=d("Link");return p(),o("div",null,[s[26]||(s[26]=i("h1",{id:"用户、組及其它-linux-特性",tabindex:"-1"},[e("用户、組及其它 Linux 特性 "),i("a",{class:"header-anchor",href:"#用户、組及其它-linux-特性","aria-label":"Permalink to “用户、組及其它 Linux 特性”"},"​")],-1)),s[27]||(s[27]=i("blockquote",null,[i("p",null,"Linux 和其他類 Unix 操作系統依賴於用户組，而不是逐個為用户分配權限和特權。一個組就是你想像的那樣：一羣在某種程度上相關的用户。")],-1)),s[28]||(s[28]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/flamingo-2458782_1920.jpg?itok=_gkzGGx5",alt:""})],-1)),i("p",null,[s[2]||(s[2]=e("到這個階段，",-1)),t(a,{href:"https://linux.cn/article-10066-1.html"},{default:n(()=>[...s[0]||(s[0]=[e("在看到如何操作目錄或文件夾之後",-1)])]),_:1}),s[3]||(s[3]=e("，但在讓自己一頭扎進文件之前，我們必須重新審視 ",-1)),s[4]||(s[4]=i("em",null,"權限",-1)),s[5]||(s[5]=e("、",-1)),s[6]||(s[6]=i("em",null,"用户",-1)),s[7]||(s[7]=e(" 和 ",-1)),s[8]||(s[8]=i("em",null,"組",-1)),s[9]||(s[9]=e("。幸運的是，",-1)),t(a,{href:"https://www.linux.com/learn/understanding-linux-file-permissions"},{default:n(()=>[...s[1]||(s[1]=[e("有一個網站上已經有了一個優秀而全面的教程，講到了權限",-1)])]),_:1}),s[10]||(s[10]=e("，所以你應該去立刻閲讀它。簡而言之，你使用權限來確定誰可以對文件和目錄執行操作，以及他們可以對每個文件和目錄執行什麼操作 —— 從中讀取、寫入、移動、擦除等等。",-1))]),s[29]||(s[29]=r(`<p>要嘗試本教程涵蓋的所有內容，你需要在系統上創建新用户。讓我們實踐起來，為每一個需要借用你電腦的人創建一個用户，我們稱之為 <code>guest</code> 賬户。</p><p><strong>警告：</strong> 例如，如果你錯誤地刪除了自己的用户和目錄，那麼創建用户，特別是刪除用户以及主目錄會嚴重損壞系統。你可能不想在你日常的工作機中練習，那麼請在另一台機器或者虛擬機上練習。無論你是否想要安全地練習，經常備份你的東西總是一個好主意。檢查備份是否正常工作，為你自己以後避免很多咬牙切齒的事情。</p><h3 id="一個新用户" tabindex="-1">一個新用户 <a class="header-anchor" href="#一個新用户" aria-label="Permalink to “一個新用户”">​</a></h3><p>你可以使用 <code>useradd</code> 命令來創建一個新用户。使用超級用户或 root 權限運行 <code>useradd</code>，即使用 <code>sudo</code> 或 <code>su</code>，這具體取決於你的系統，你可以：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo useradd -m guest</span></span></code></pre></div><p>然後輸入你的密碼。或者也可以這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>su -c &quot;useradd -m guest&quot;</span></span></code></pre></div><p>然後輸入 root 或超級用户的密碼。</p><p>（ <em>為了簡潔起見，我們將從現在開始假設你使用 <code>sudo</code> 獲得超級用户或 root 權限。</em> ）</p><p>通過使用 <code>-m</code> 參數，<code>useradd</code> 將為新用户創建一個主目錄。你可以通過列出 <code>/home/guest</code> 來查看其內容。</p><p>然後你可以使用以下命令來為新用户設置密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo passwd guest</span></span></code></pre></div><p>或者你也可以使用 <code>adduser</code>，這是一個交互式的命令，它會詢問你一些問題，包括你要為用户分配的 shell（是的，shell 有不止一種），你希望其主目錄在哪裏，你希望他們屬於哪些組（有關這點稍後會講到）等等。在運行 <code>adduser</code> 結束時，你可以設置密碼。注意，默認情況下，在許多發行版中都沒有安裝 <code>adduser</code>，但安裝了 <code>useradd</code>。</p><p>順便説一下，你可以使用 <code>userdel</code> 來移除一個用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo userdel -r guest</span></span></code></pre></div><p>使用 <code>-r</code> 選項，<code>userdel</code> 不僅刪除了 <code>guest</code> 用户，還刪除了他們的主目錄和郵件中的條目（如果有的話）。</p><h3 id="主目錄中的內容" tabindex="-1">主目錄中的內容 <a class="header-anchor" href="#主目錄中的內容" aria-label="Permalink to “主目錄中的內容”">​</a></h3><p>談到用户的主目錄，它依賴於你所使用的發行版。你可能已經注意到，當你使用 <code>-m</code> 選項時，<code>useradd</code> 使用子目錄填充用户的目錄，包括音樂、文檔和諸如此類的內容以及各種各樣的隱藏文件。要查看 <code>guest</code> 主目錄中的所有內容，運行 <code>sudo ls -la /home/guest</code>。</p><p>進入新用户目錄的內容通常是由 <code>/etc/skel</code> 架構目錄確定的。有時它可能是一個不同的目錄。要檢查正在使用的目錄，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>useradd -D</span></span>
<span class="line"><span>GROUP=100</span></span>
<span class="line"><span>HOME=/home</span></span>
<span class="line"><span>INACTIVE=-1</span></span>
<span class="line"><span>EXPIRE=</span></span>
<span class="line"><span>SHELL=/bin/bash</span></span>
<span class="line"><span>SKEL=/etc/skel</span></span>
<span class="line"><span>CREATE_MAIL_SPOOL=no</span></span></code></pre></div><p>這會給你一些額外的有趣信息，但你現在感興趣的是 <code>SKEL=/etc/skel</code> 這一行，在這種情況下，按照慣例，它指向 <code>/etc/skel/</code>。</p><p>由於 Linux 中的所有東西都是可定製的，因此你可以更改那些放入新創建的用户目錄的內容。試試這樣做：在 <code>/etc/skel/</code> 中創建一個新目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir /etc/skel/Documents</span></span></code></pre></div><p>然後創建一個包含歡迎消息的文件，並將其複製過來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp welcome.txt /etc/skel/Documents</span></span></code></pre></div><p>現在刪除 <code>guest</code> 賬户:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo userdel -r guest</span></span></code></pre></div><p>再次創建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo useradd -m guest</span></span></code></pre></div><p>嘿！你的 <code>Documents/</code> 目錄和 <code>welcome.txt</code> 文件神奇地出現在了 <code>guest</code> 的主目錄中。</p><p>你還可以在創建用户時通過編輯 <code>/etc/default/useradd</code> 來修改其他內容。我的看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GROUP=users</span></span>
<span class="line"><span>HOME=/home</span></span>
<span class="line"><span>INACTIVE=-1</span></span>
<span class="line"><span>EXPIRE=</span></span>
<span class="line"><span>SHELL=/bin/bash</span></span>
<span class="line"><span>SKEL=/etc/skel</span></span>
<span class="line"><span>CREATE_MAIL_SPOOL=no</span></span></code></pre></div><p>這些選項大多數都是不言自明的，但讓我們仔細看看 <code>GROUP</code> 選項。</p><h3 id="羣組心態" tabindex="-1">羣組心態 <a class="header-anchor" href="#羣組心態" aria-label="Permalink to “羣組心態”">​</a></h3><p>Linux 和其他類 Unix 操作系統依賴於用户組，而不是逐個為用户分配權限和特權。一個組就是你想像的那樣：一羣在某種程度上相關的用户。在你的系統上可能有一組允許使用打印機的用户，他們屬於 <code>lp</code>（即 “<em>line printer</em>”）組。傳統上 <code>wheel</code> 組的成員是唯一可以通過使用 <code>su</code> 成為超級用户或 root 的成員。<code>network</code> 用户組可以啓動或關閉網絡。還有許多諸如此類的。</p><p>不同的發行版有不同的組，具有相同或相似名稱的組具有不同的權限，這也取決於你使用的發行版。因此，如果你在前一段中讀到的內容與你係統中的內容不匹配，不要感到驚訝。</p><p>不管怎樣，要查看系統中有哪些組，你可以使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>getent group</span></span></code></pre></div><p><code>getent</code> 命令列出了某些系統資料庫的內容。</p><p>要查找當前用户所屬的組，嘗試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>groups</span></span></code></pre></div><p>當你使用 <code>useradd</code> 創建新用户時，除非你另行指定，否則用户將只屬於一個組：他們自己。<code>guest</code> 用户屬於 <code>guest</code> 組。組使用户有權管理自己的東西，僅此而已。</p><p>你可以使用 <code>groupadd</code> 命令創建新組，然後添加用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo groupadd photos</span></span></code></pre></div><p>例如，這將創建 <code>photos</code> 組。下一次，我們將使用它來構建一個共享目錄，該組的所有成員都可以讀取和寫入，我們將更多地瞭解權限和特權。敬請關注！</p><hr>`,46)),i("p",null,[s[12]||(s[12]=e("via: ",-1)),t(a,{href:"https://www.linux.com/learn/intro-to-linux/2018/7/users-groups-and-other-linux-beasts"},{default:n(()=>[...s[11]||(s[11]=[e("https://www.linux.com/learn/intro-to-linux/2018/7/users-groups-and-other-linux-beasts",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=e("作者：",-1)),t(a,{href:"https://www.linux.com/users/bro66"},{default:n(()=>[...s[13]||(s[13]=[e("Paul Brown",-1)])]),_:1}),s[18]||(s[18]=e(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[14]||(s[14]=[e("lujun9972",-1)])]),_:1}),s[19]||(s[19]=e(" 譯者：",-1)),t(a,{href:"https://github.com/MjSeven"},{default:n(()=>[...s[15]||(s[15]=[e("MjSeven",-1)])]),_:1}),s[20]||(s[20]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[16]||(s[16]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[23]||(s[23]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:n(()=>[...s[22]||(s[22]=[e("Linux中國",-1)])]),_:1}),s[25]||(s[25]=e(" 榮譽推出",-1))])])}const y=l(u,[["render",g]]);export{C as __pageData,y as default};
